import type { SoundDefinition, SoundPatch } from "@litlab/audx";
import {
	getSoundInfo,
	SOUND_CATEGORIES,
	type SoundCategory,
} from "@litlab/audx/catalog";
import mechanicalTheme from "@/.themes/mechanical.json";
import minimalTheme from "@/.themes/minimal.json";
import playfulTheme from "@/.themes/playful.json";
import retroTheme from "@/.themes/retro.json";

/** Built-in themes, in display order. Generated by `bun run sounds:build`. */
export const BUILT_IN_THEMES = {
	minimal: minimalTheme as SoundPatch,
	playful: playfulTheme as SoundPatch,
	mechanical: mechanicalTheme as SoundPatch,
	retro: retroTheme as SoundPatch,
} as const;

export type AudioThemeName = keyof typeof BUILT_IN_THEMES;

export const THEME_NAMES = Object.keys(BUILT_IN_THEMES) as AudioThemeName[];

export function isBuiltInTheme(name: string): name is AudioThemeName {
	return name in BUILT_IN_THEMES;
}

export type AudioCatalogItem = {
	name: string;
	title: string;
	description?: string;
	category: string;
	theme: AudioThemeName;
	definition: SoundDefinition;
	meta: {
		theme: AudioThemeName;
		semanticName: string;
		duration: number;
	};
};

export type ThemeCatalogItem = {
	name: AudioThemeName;
	displayName: string;
	description?: string;
	soundCount: number;
	mappedCount: number;
};

export type CategoryCount = {
	name: string;
	count: number;
};

export function getAllThemes(): ThemeCatalogItem[] {
	return THEME_NAMES.map((name) => {
		const theme = BUILT_IN_THEMES[name];
		const count = Object.keys(theme.sounds).length;
		return {
			name,
			displayName: toTitle(theme.name),
			description: theme.description,
			soundCount: count,
			mappedCount: count,
		};
	});
}

export function getAllAudio(): AudioCatalogItem[] {
	return THEME_NAMES.flatMap((theme) =>
		Object.entries(BUILT_IN_THEMES[theme].sounds).map(
			([soundName, definition]) =>
				createAudioItem(theme, soundName, definition),
		),
	);
}

const CATEGORY_ORDER = new Map<string, number>(
	SOUND_CATEGORIES.map((c, i) => [c.name, i]),
);

export function getCategoriesForItems(
	items: AudioCatalogItem[],
): CategoryCount[] {
	const counts = new Map<string, number>();
	for (const item of items) {
		counts.set(item.category, (counts.get(item.category) ?? 0) + 1);
	}
	return Array.from(counts.entries())
		.map(([name, count]) => ({ name, count }))
		.sort(
			(a, b) =>
				(CATEGORY_ORDER.get(a.name) ?? 99) - (CATEGORY_ORDER.get(b.name) ?? 99),
		);
}

export function formatDuration(seconds: number): string {
	if (seconds < 1) return `${Math.round(seconds * 1000)}ms`;
	return `${seconds.toFixed(1)}s`;
}

export function formatSizeKb(size: number): string {
	return `${Math.round(size)} KB`;
}

export function getAudioByName(name: string): AudioCatalogItem | undefined {
	return getAllAudio().find((item) => item.name === name);
}

function createAudioItem(
	theme: AudioThemeName,
	soundName: string,
	definition: SoundDefinition,
): AudioCatalogItem {
	const info = getSoundInfo(soundName);
	return {
		name: `audio/${theme}/${soundName}`,
		title: toTitle(soundName),
		description: info?.description,
		category: (info?.category ?? "other") satisfies SoundCategory | "other",
		theme,
		definition,
		meta: {
			theme,
			semanticName: soundName,
			duration: getDuration(definition),
		},
	};
}

function getDuration(definition: SoundDefinition): number {
	if ("layers" in definition) {
		return Math.max(
			...definition.layers.map(
				(layer) => (layer.delay ?? 0) + getDuration(layer),
			),
		);
	}

	const envelope = definition.envelope ?? { decay: 0.5 };
	const effectsTail = definition.effects?.reduce((tail, effect) => {
		if (effect.type === "delay") return Math.max(tail, effect.time ?? 0.25);
		if (effect.type === "reverb") return Math.max(tail, effect.decay ?? 0.5);
		return tail;
	}, 0);

	return (
		(envelope.attack ?? 0) +
		envelope.decay +
		(envelope.release ?? 0) +
		(effectsTail ?? 0)
	);
}

function toTitle(value: string): string {
	return value
		.split(/[-_\s]+/)
		.map((part) => part.charAt(0).toUpperCase() + part.slice(1))
		.join(" ");
}
